import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/BINOMIAL.md","filePath":"manual-en/BINOMIAL.md","lastUpdated":1785684581000}'),s={name:"manual-en/BINOMIAL.md"};function i(n,e,h,l,p,d){return a(),o("div",null,[...e[0]||(e[0]=[r(`<h4 id="_15-12-1-binomial-test" tabindex="-1">15.12.1 Binomial test <a class="header-anchor" href="#_15-12-1-binomial-test" aria-label="Permalink to &quot;15.12.1 Binomial test&quot;">​</a></h4><pre><code>     [ /BINOMIAL[(p)]=var_list[(value1[, value2)] ] ]
</code></pre><p>The <code>/BINOMIAL</code> subcommand compares the observed distribution of a dichotomous variable with that of a binomial distribution. The variable p specifies the test proportion of the binomial distribution. The default value of 0.5 is assumed if p is omitted.</p><p>If a single value appears after the variable list, then that value is used as the threshold to partition the observed values. Values less than or equal to the threshold value form the first category. Values greater than the threshold form the second category.</p><p>If two values appear after the variable list, then they are used as the values which a variable must take to be in the respective category. Cases for which a variable takes a value equal to neither of the specified values, take no part in the test for that variable.</p><p>If no values appear, then the variable must assume dichotomous values. If more than two distinct, non-missing values for a variable under test are encountered then an error occurs.</p><p>If the test proportion is equal to 0.5, then a two-tailed test is reported. For any other test proportion, a one-tailed test is reported. For one-tailed tests, if the test proportion is less than or equal to the observed proportion, then the significance of observing the observed proportion or more is reported. If the test proportion is more than the observed proportion, then the significance of observing the observed proportion or less is reported. That is to say, the test is always performed in the observed direction.</p><p>PSPP uses a very precise approximation to the gamma function to compute the binomial significance. Thus, exact results are reported even for very large sample sizes.</p>`,8)])])}const m=t(s,[["render",i]]);export{c as __pageData,m as default};
